function CalculateCommitCount(GitPassword,GITTestRepoURLCommits) {
	let responseJSON = Resources["ContentLoaderFunctions"].LoadJSON({
		headers: {
			"Authorization": "Bearer " + GitPassword,
			"Content-Type": "application/json"
		} /* JSON */ ,
		ignoreSSLErrors: true /* BOOLEAN */ ,
		url: GITTestRepoURLCommits /* STRING */
	});
    let responseHeaders = responseJSON.responseHeaders;
	let last;
	if (responseHeaders.Link) {
		last = responseHeaders.Link;
		let lastCommitPageURL = last.split(",")[1].split(";")[0].replace("<", "").replace(">", "").trim();
		let lastPageCommitCount =  Resources["ContentLoaderFunctions"].LoadJSON({
			headers: {
				"Authorization": "Bearer " + GitPassword,
				"Content-Type": "application/json"
			} /* JSON */ ,
			ignoreSSLErrors: true /* BOOLEAN */ ,
			url: lastCommitPageURL /* STRING */
		}).array.length;	
        //GitHub API is paginated, with default 30 commits each page; the final commit count needs to be calculated
		return (lastCommitPageURL.split("?")[1].split("=")[1]-1)*30+lastPageCommitCount;
	} else return responseJSON.array.length;


}


