let testResult;
//Input data is defined in the CreateTestData Service
try {
	let iftbl_EntitiesToExport = DataShapes["SpotlightSearch"].CreateValues();

	//1. Create a Project as holder of all entities
	Resources["EntityServices"].CreateProject({
		dependsOn: undefined /* STRING */ ,
		name: InputParams.ProjectName /* STRING */ ,
