	});
	//2. Create a test Thing in this project
	Resources["EntityServices"].CreateThing({
		name: InputParams.ThingName /* STRING */ ,
		description: "Thing created automatically for testing purposes." /* STRING */ ,
		thingTemplateName: "GenericThing" /* THINGTEMPLATENAME */ ,
		projectName: InputParams.ProjectName /* PROJECTNAME */ ,
		tags: undefined /* TAGS */
	});
	Things[InputParams.ThingName].RestartThing();
	iftbl_EntitiesToExport.AddRow({
		type: "Thing", // STRING [Primary Key]
		name: InputParams.ThingName, // STRING [Primary Key]
	});
	//3. Create a test ThingTemplate in this project
	Resources["EntityServices"].CreateThingTemplate({
		name: InputParams.ThingTemplateName /* STRING */ ,
		description: "Thing Template created automatically for testing purposes." /* STRING */ ,
		thingTemplateName: "GenericThing" /* THINGTEMPLATENAME */ ,
		projectName: InputParams.ProjectName /* PROJECTNAME */ ,
		tags: undefined /* TAGS */
	});
	iftbl_EntitiesToExport.AddRow({
		type: "ThingTemplate", // STRING [Primary Key]
		name: InputParams.ThingTemplateName, // STRING [Primary Key]
	});
	//4. Create a test ThingShape in this project
	Resources["EntityServices"].CreateThingShape({
		name: InputParams.ThingShapeName /* STRING */ ,
		description: "Thing Shape created automatically for testing purposes." /* STRING */ ,
		projectName: InputParams.ProjectName /* PROJECTNAME */ ,
		tags: undefined /* TAGS */
	});
	iftbl_EntitiesToExport.AddRow({
		type: "ThingShape", // STRING [Primary Key]
		name: InputParams.ThingShapeName, // STRING [Primary Key]
	});
	//5. Create a test ModelTag in this project
	Resources["EntityServices"].CreateModelTagVocabulary({
		name: InputParams.ModelTagName /* STRING */ ,
		description: "ModelTagVocabulary created automatically for testing purposes." /* STRING */ ,
		dynamic: true /* BOOLEAN */ ,
		projectName: InputParams.ProjectName /* PROJECTNAME */ ,
		tags: undefined /* TAGS */
	});
	iftbl_EntitiesToExport.AddRow({
		type: "ModelTagVocabulary", // STRING [Primary Key]
		name: InputParams.ModelTagName, // STRING [Primary Key]
	});
	//6. Export the created Project entities in the working folder, to prepare for Push
	// Values: INFOTABLE dataShape: ""
	Things[InputParams.GitThingName].ExportProjectEntities({
		ProjectName: InputParams.ProjectName /* STRING */ ,
		includeDependents: false /* BOOLEAN */ ,
		EntitiesToExport: iftbl_EntitiesToExport /* INFOTABLE {"dataShape":"SpotlightSearch"} */
	});
	Things[InputParams.GitThingName].Push({
		Message: "Push created automatically for testing purposes." /* STRING */
	});
	//once Push is done, we'll look at the last Commit to see if it contains these files
	let iftbl_CommitList = Things[InputParams.GitThingName].GetCommitList();
	//    logger.warn("Git Thing in Push"+InputParams.GitThingName);
	//	logger.warn("Git Thing Commit List in Push"+Things[InputParams.GitThingName].GetCommitList().ToJSON());
	//    logger.warn("Commit ID in Push: "+iftbl_CommitList.getRow(0).CommitID);
	let iftbl_ChangedFiles = Things[InputParams.GitThingName].GetCommitInfo({
		CommitID: iftbl_CommitList.getRow(0).CommitID
	}).ChangedFiles;
	logger.warn("Changed Files in commit: " + Things[InputParams.GitThingName].GetCommitInfo({
		CommitID: iftbl_CommitList.getRow(0).CommitID
	}).ChangedFiles.ToJSON());
	logger.warn("EntitiesToExport: " + iftbl_EntitiesToExport.ToJSON());
	//we'll verify if all the Entities to be exported are found in the list of changed files from the commit
	logger.warn("Result of Push test:" + iftbl_EntitiesToExport.rows.toArray().every(exportedEntity => iftbl_ChangedFiles.rows.toArray().some(changedFile => changedFile.FileName.includes(exportedEntity.name))));
	testResult = iftbl_EntitiesToExport.rows.toArray().every(exportedEntity => iftbl_ChangedFiles.rows.toArray().some(changedFile => changedFile.FileName.includes(exportedEntity.name)));


	const exportedEntities = iftbl_EntitiesToExport.rows.toArray();
	const changedFiles = iftbl_ChangedFiles.rows.toArray();

	let allMatched = true;

	exportedEntities.forEach(exportedEntity => {
		const matchFound = changedFiles.some(changedFile =>
			changedFile.FileName.toLowerCase().includes(exportedEntity.name.toLowerCase())
		);

		if (!matchFound) {
			logger.warn("No match found for exported entity: " + exportedEntity.name);
			allMatched = false;
		}
	});

	logger.warn("Result of Push test: " + allMatched);

	//testResult = (Projects[InputParams.ProjectName] && Things[InputParams.ThingName] && ThingTemplates[InputParams.ThingTemplateName] && ThingShapes[InputParams.ThingShapeName] && ModelTags[InputParams.ModelTagName]) ? true : false;

} catch (err) {
	testResult = false;
	logger.warn(err);
}

