// AddOrUpdateDataTableEntry(tags:TAGS, source:STRING("me.name"), values:INFOTABLE(TestResultsDT), location:LOCATION):STRING
//var id = Things["TestResultsDT"].AddOrUpdateDataTableEntry(params);
result = PreviousTestResults;
logger.warn("---Ended test --- " + TestName);


//1. Initializing the test data. Optional.
let testData = me.CreateTestData();

//2. Create a variable that will store all the results 
var prevTestResult= Resources["InfoTableFunctions"].CreateInfoTableFromDataShape({
    infoTableName : "InfoTable",
    dataShapeName : "TestResultData"
});

//3. The CreateTestData contains service Names for each test; we will iterate through those

for (var i = 0; i < testData.tests.length; i++) {  

   // logger.warn("Starting to execute Test: "+testData.tests[i].ServiceName +"; Test index: "+i);
    pause(10);
    prevTestResult=me[testData.tests[i].ServiceName]({PreviousTestResults:prevTestResult,
                                TestName: testData.tests[i].TestName /* STRING */,
								InputParams: testData.tests[i].InputParams /* JSON */,
								ExpectedOutput: testData.tests[i].ExpectedOutput  /* JSON */}); 
    pause(10);
   // logger.warn("Finished to execute Test: "+testData.tests[i].ServiceName +"; Test index: "+i);

}
//4. delete test data
pause(50);
me.DeleteTestData({InputParams:testData});
result = prevTestResult;
